arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-5e34f8edc9704c7a81fbed04404efd83/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

**Architecture**: Interactive Auto, Global scope. Two projects:
- `ShipmentTracker` (server) — hosts app, APIs, EF Core
- `ShipmentTracker.Client` (WebAssembly) — all interactive UI components

**Key rule**: Interactive components MUST go in `.Client`. Data access from interactive components must go through HTTP APIs (not direct DbContext).

## What to implement

### 1. Shared Models in `.Client` project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class ShipmentSummary
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CarrierName { get; set; } = string.Empty;
    public double WeightKg { get; set; }
}
```

### 2. Service Interface in `.Client` project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null);
    Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentSummary?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus);
}
```

### 3. Client-side HTTP implementation in `.Client` project

Create `ShipmentTracker.Client/Services/HttpShipmentService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = new List<string>();
        if (!string.IsNullOrEmpty(statusFilter)) query.Add($"status={Uri.EscapeDataString(statusFilter)}");
        if (!string.IsNullOrEmpty(searchTerm)) query.Add($"search={Uri.EscapeDataString(searchTerm)}");
        var url = "api/shipments" + (query.Count > 0 ? "?" + string.Join("&", query) : "");
        return await http.GetFromJsonAsync<List<ShipmentSummary>>(url) ?? [];
    }

    public async Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await http.GetFromJsonAsync<ShipmentSummary>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<ShipmentSummary?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentSummary>();
    }
}
```

### 4. Register services in Client `Program.cs`

Update `ShipmentTracker.Client/Program.cs` to add:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, HttpShipmentService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

### 5. Server-side EF Core Entity and DbContext

Create `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(100)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(100)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }

    [MaxLength(100)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(50)]
    public string CarrierName { get; set; } = string.Empty;

