using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(IServiceScopeFactory scopeFactory) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == (int)status);
        }

        if (!string.IsNullOrEmpty(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(s =>
                s.TrackingNumber.ToLower().Contains(term) ||
                s.Destination.ToLower().Contains(term) ||
                s.RecipientName.ToLower().Contains(term));
        }

        return await query.OrderByDescending(s => s.ShippedDate)
            .Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (ShipmentStatus)s.Status,
                ShippedDate = s.ShippedDate,
                EstimatedDelivery = s.EstimatedDelivery,
                ActualDelivery = s.ActualDelivery,
                RecipientName = s.RecipientName,
                CarrierName = s.CarrierName,
                WeightKg = s.WeightKg
            })
            .ToListAsync();
    }

    public async Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        var s = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (s is null) return null;

        return new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = (ShipmentStatus)s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            CarrierName = s.CarrierName,
            WeightKg = s.WeightKg
        };
    }

    public async Task<ShipmentSummary?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return null;

        shipment.Status = (int)newStatus;
        if (newStatus == ShipmentStatus.Delivered)
        {
            shipment.ActualDelivery = DateTime.UtcNow;
        }
        await db.SaveChangesAsync();

        return new ShipmentSummary
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
